import{_ as e,c as o,o as a,ag as d}from"./chunks/framework.Bzez9NG9.js";const g=JSON.parse('{"title":"System settings","description":"Reference SPACE configuration values for logging, log synchronization and exports, file uploads, model search cache freshness, Python packages, and AI profile defaults.","frontmatter":{"title":"System settings","description":"Reference SPACE configuration values for logging, log synchronization and exports, file uploads, model search cache freshness, Python packages, and AI profile defaults.","keywords":["LOG_LEVEL","PYTHON_PACKAGES","MODEL_SEARCH_CACHE_TTL_HOURS","temperature"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/system-settings.md","filePath":"doc/configuration/system-settings.md"}'),r={name:"doc/configuration/system-settings.md"};function s(n,t,i,c,l,h){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="system-settings" tabindex="-1">System settings <a class="header-anchor" href="#system-settings" aria-label="Permalink to &quot;System settings&quot;">​</a></h1><p>Open <strong>SPACE settings → Configuration</strong> to view system settings. The table shows each setting&#39;s name, description, and current value. Use <strong>Search</strong> to find a setting, <strong>Edit</strong> to change it, and <strong>Refresh</strong> to reload the displayed values.</p><p>Displayed values belong to your SPACE instance; they are not a list of product defaults.</p><h2 id="space-logging" tabindex="-1">SPACE logging <a class="header-anchor" href="#space-logging" aria-label="Permalink to &quot;SPACE logging&quot;">​</a></h2><p>These settings control SPACE diagnostic logging. To inspect platform activity, open <a href="./journal.html">Journal</a>; to investigate TM1 events, use <a href="./../planning-analytics/logs.html">Logs</a>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>LOG_LEVEL</code></td><td>Log verbosity: <code>1</code> = INFO, <code>2</code> = DEBUG, <code>3</code> = EXTENDED DEBUG.</td></tr><tr><td><code>LOG_EXTENDED_MAX_SIZE</code></td><td>Maximum size in bytes before extended log messages are truncated.</td></tr></tbody></table><h2 id="log-synchronization-and-exports" tabindex="-1">Log synchronization and exports <a class="header-anchor" href="#log-synchronization-and-exports" aria-label="Permalink to &quot;Log synchronization and exports&quot;">​</a></h2><p>Batch settings control how much data is processed per request or insert. Content retention is configured under <a href="./content.html">Content</a>, and update schedules under <a href="./jobs.html">Jobs</a>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>AUDIT_LOG_BATCH_DAYS</code></td><td>Days of audit logs to fetch per request.</td></tr><tr><td><code>AUDIT_LOG_BATCH_RECORDS</code></td><td>Audit log records to fetch per request.</td></tr><tr><td><code>TRANSACTION_LOG_BATCH_DAYS</code></td><td>Days of transaction logs to fetch per request.</td></tr><tr><td><code>TRANSACTION_LOG_BATCH_RECORDS</code></td><td>Transaction log records to fetch per request.</td></tr><tr><td><code>SERVER_LOG_BATCH_DAYS</code></td><td>Days of server logs to fetch per request.</td></tr><tr><td><code>SERVER_LOG_BATCH_RECORDS</code></td><td>Server log records to fetch per request.</td></tr><tr><td><code>CLICKHOUSE_INSERT_BATCH_SIZE</code></td><td>Rows per ClickHouse insert batch.</td></tr><tr><td><code>LOG_EXPORT_LIMIT</code></td><td>Maximum records per log export.</td></tr></tbody></table><h2 id="file-uploads" tabindex="-1">File uploads <a class="header-anchor" href="#file-uploads" aria-label="Permalink to &quot;File uploads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>UPLOAD_FILE_MAX_MB</code></td><td>Maximum uploaded file size in MB before the upload is rejected.</td></tr><tr><td><code>UPLOAD_FILE_STREAM_CHUNK_MB</code></td><td>Chunk size in MB when streaming uploaded files to disk.</td></tr><tr><td><code>UPLOAD_FILE_BATCH_RECORDS</code></td><td>Log records per batch when inserting uploaded files into ClickHouse.</td></tr></tbody></table><h2 id="model-search-cache" tabindex="-1">Model search cache <a class="header-anchor" href="#model-search-cache" aria-label="Permalink to &quot;Model search cache&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>MODEL_SEARCH_CACHE_TTL_HOURS</code></td><td>Hours before the Model search cache is considered stale and should be refreshed.</td></tr></tbody></table><p>See <a href="./../planning-analytics/model-search.html">Model search</a> for searching objects and refreshing the cache.</p><h2 id="python-packages" tabindex="-1">Python packages <a class="header-anchor" href="#python-packages" aria-label="Permalink to &quot;Python packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PYTHON_PACKAGES</code></td><td>Additional Python packages installed in the Python/Jupyter environment.</td></tr></tbody></table><p>See <a href="./../python/custom-packages.html">Custom packages</a> for the installation details still to be documented, and <a href="./../python/">Python</a> for the workspace overview.</p><h2 id="ai-profile-defaults" tabindex="-1">AI profile defaults <a class="header-anchor" href="#ai-profile-defaults" aria-label="Permalink to &quot;AI profile defaults&quot;">​</a></h2><p>These values apply when the corresponding setting is not explicitly set in an AI profile. See <a href="./ai.html">AI configuration</a> for profile settings.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>AI_DEFAULT_MAX_INPUT_TOKENS</code></td><td>Default maximum input tokens for an AI profile.</td></tr><tr><td><code>AI_DEFAULT_MAX_OUTPUT_TOKENS</code></td><td>Default maximum output tokens for an AI profile.</td></tr><tr><td><code>AI_DEFAULT_TEMPERATURE</code></td><td>Default temperature for an AI profile.</td></tr></tbody></table>',20)]))}const u=e(r,[["render",s]]);export{g as __pageData,u as default};
